/// Test seam only — e2e cannot wait out the real hour.
/// The refusal over unticked summary boxes (T-713, T-735), one wording for
/// every road — a move into a `requires_ticked` column, `a a`, the crown's
/// `archive_ticket` — with `what` saying which: `before DONE`, `to archive
/// from DONE`.
/// What a ticket's notes are at: every write bumps a note's `rev` and stamps
/// its `edited_at`, a delete takes its id off, a new note adds one.
fn notes_key(notes: &[mesimon_core::board::NoteMeta]) -> u64 {
    use std::hash::{Hash, Hasher};
    let mut h = std::collections::hash_map::DefaultHasher::new();
    for n in notes {
        (n.id, n.rev, &n.edited_at).hash(&mut h);
    }
    h.finish()
}

/// A fact derived from a ticket's note bodies, kept under `notes_key` of
/// its notes when read and read again only once a write moved the key:
/// the archive offer's open-box count (T-840), the forge's `Summary`
/// addresses (T-859). `write_note` forgets the ticket's besides.
struct NoteFacts<T>(std::cell::RefCell<HashMap<ulid::Ulid, (u64, T)>>);

impl<T> Default for NoteFacts<T> {
    fn default() -> Self {
        Self(Default::default())
    }
}

impl<T: Clone> NoteFacts<T> {
    /// The fact kept under `key`, or `read` run and kept under it.
    fn get_or(&self, id: ulid::Ulid, key: u64, read: impl FnOnce() -> T) -> T {
        if let Some((k, fact)) = self.0.borrow().get(&id) {
            if *k == key {
                return fact.clone();
            }
        }
        let fact = read();
        self.put(id, key, fact.clone());
        fact
    }

    fn put(&self, id: ulid::Ulid, key: u64, fact: T) {
        self.0.borrow_mut().insert(id, (key, fact));
    }

    fn forget(&mut self, id: ulid::Ulid) {
        self.0.get_mut().remove(&id);
    }
}

/// An entry as the ledger or a tail spells it (T-859) — a URL, or an act's
/// number — made an address on the ticket's one repository; a bare number
/// with no such repository names no one.
fn entry_url(entry: &str, repo: Option<&mesimon_core::forge::Remote>) -> Option<String> {
    match repo {
        Some(r) => mesimon_core::forge::acted_url(entry, r),
        None => mesimon_core::forge::pr_number_of(entry).map(|_| entry.to_string()),
    }
}

/// Whose words `park_ask` parks: a person's, the crown's agent's (its
/// ticket) or a linked board's crown's (T-733).
enum Asker {
    Person,
    Agent(ulid::Ulid),
    Board(peer::FromBoard),
}

/// Every PR a ticket named (T-859), as addresses (`named_prs`), in two
/// lists that share none (T-875): together what a forge read matches and
/// reads by itself.
struct NamedPrs {
    /// The URLs its `pr create`s printed.
    created: Vec<String>,
    /// The acted on and the `Summary`'s, the rest: read as reviewed when
    /// found that way, and what the board's switch may keep out.
    theirs: Vec<String>,
    /// The one repository the ticket's bare numbers are on (`ticket_repo`).
    repo: Option<mesimon_core::forge::Remote>,
    /// The `Summary`'s addresses alone (`summary_prs_of`).
    summary: std::sync::Arc<[String]>,
}

impl NamedPrs {
    fn is_empty(&self) -> bool {
        self.created.is_empty() && self.theirs.is_empty()
    }

    /// Both lists as one, the `pr create`s' first.
    fn into_all(self) -> Vec<String> {
        let mut all = self.created;
        all.extend(self.theirs);
        all
    }
}

fn open_boxes_refusal(open: usize, what: &str) -> Option<String> {
    match open {
        0 => None,
        1 => Some(format!("1 summary box is unticked — tick it or take it out {what}")),
        n => Some(format!("{n} summary boxes are unticked — tick them or take them out {what}")),
    }
}

/// A Claude seat whose conversation never took a prompt (T-603): no file at
/// the transcript path `SessionStart` named — Claude Code writes none before
/// the first prompt (measured on 2.1.288). No path is no `SessionStart`, so
/// nothing is known.
fn never_prompted(rec: &mesimon_core::board::SessionRecord) -> bool {
    rec.kind == SessionKind::Claude
        && rec.transcript_path.as_deref().is_some_and(|p| !std::path::Path::new(p).is_file())
}

/// Whether a brief the last daemon handed over goes again by itself
/// (T-722): the seat sits at the composer `SessionStart` left, with a pane,
/// and its conversation took no prompt by either reading (`history_missing`
/// is where a wake looks for it). A seat that took one, or stopped on
/// anything else, keeps the mark for a person.
fn restart_resends(rec: &mesimon_core::board::SessionRecord, history_missing: bool) -> bool {
    rec.unsent.as_ref().is_some_and(|u| u.brief)
        && rec.state == (SessionState::Idle { stop_reason: StopReason::Unknown })
        && never_prompted(rec)
        && history_missing
}

fn archive_suggest_ms() -> u64 {
    std::env::var("MESIMON_ARCHIVE_SUGGEST_MS")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(ARCHIVE_SUGGEST_MS)
}

/// The process table — pid, parent, age and name — for `bash_mode_foreground`
/// (T-707). `ps axo` is BSD and procps alike; an unreadable table is empty,
/// never an error: a missing `ps` only means no `!` command is ever seen.
/// A record of ours with a pane on the private server: what the wholesale
/// server guard watches. Not `Sleeping` (no pane, no process) and not an
/// observe-only adopted record (its process lives in the user's own
/// terminal, not our tmux).
fn ours_paned(r: &SessionRecord) -> bool {
    r.state.has_pane() && !r.observe_only()
}

/// An idle Claude at its prompt (T-707): the states in which a `!` command
/// typed into the composer is the pane's foreground.
fn idle_at_prompt(state: &SessionState) -> bool {
    matches!(
        state,
        SessionState::Idle {
            stop_reason: StopReason::EndTurn
                | StopReason::Interrupted
                | StopReason::Unknown
                | StopReason::Monitoring
        }
    )
}

/// A Claude seat the startup probe reads the screen of: on its way up, or
/// stopped at a dialog the probe recognises.
fn claude_startup_candidate(s: &SessionRecord) -> bool {
    s.kind == SessionKind::Claude
        && s.state.has_pane()
        && matches!(
            s.state,
            SessionState::Spawning
                | SessionState::RequiresAction { reason: Reason::StartupModal | Reason::Trust }
        )
}

/// The offer and its bulk action use persisted session states, never snapshot decorations.
fn archive_offer_old_enough(
    board: &Board,
    ticket: ulid::Ulid,
    created_at: &str,
    now: u64,
    threshold: u64,
) -> bool {
    if board.ticket_awake_sessions(ticket) > 0 {
        return false;
    }
    let sessions: Vec<_> = board.sessions.iter().filter(|s| s.ticket == ticket).collect();
    let sleeping: Vec<_> =
        sessions.iter().filter(|s| matches!(s.state, SessionState::Sleeping)).collect();
    if sleeping.is_empty() {
        sessions
            .iter()
            .filter_map(|s| s.state_changed_at)
            .chain(created_at_ms(created_at))
            .max()
            .is_some_and(|at| now.saturating_sub(at) >= threshold)
    } else {
        sleeping
            .iter()
            .all(|s| s.state_changed_at.is_some_and(|at| now.saturating_sub(at) >= threshold))
    }
}

/// Unreadable process evidence cannot authorize closing a person's shell.
fn shell_children_idle(children: Result<Vec<String>, String>) -> Result<(), String> {
    let children = children?;
    if children.is_empty() {
        Ok(())
    } else {
        Err(format!("bash has live children ({})", children.join(", ")))
    }
}

/// Direct live children of a pid, by name — the tmux-recast bash-sleep guard.
fn live_children(pid: i32) -> std::result::Result<Vec<String>, String> {
    let out =
        std::process::Command::new("pgrep").args(["-lP", &pid.to_string()]).output().map_err(
            |_| "could not inspect shell jobs; open the shell and exit it yourself".to_string(),
        )?;
    shells::parse_children(out.status.code(), &out.stdout)
}

/// `created_at`'s `@<unix secs>` stamp as epoch ms; None for anything else
/// (an unparsable stamp never feeds the archive suggestion).
fn created_at_ms(created_at: &str) -> Option<u64> {
    created_at.strip_prefix('@').and_then(|s| s.parse::<u64>().ok()).map(|s| s * 1000)
}

/// The longest plan `get_ticket.needs_you.plan` carries on a keyed read
/// with `plan` (T-582, T-991), past it the head marked cut (`plan_head`).
/// 64 KiB since T-936, where a design plan measured 26 KiB.
const AGENT_PLAN_MAX_BYTES: usize = 64 * 1024;

fn now_iso() -> String {
    // Seconds precision is enough for created_at; avoid a chrono dependency.
    format!("@{}", now_secs())
}

/// T-573's research seam: the plugin folder a Claude launch loads with
/// `--plugin-dir`, or nothing. Off by default; a spike, not a feature.
fn mod_dir() -> Option<std::path::PathBuf> {
    std::env::var_os("MESIMON_MOD_DIR").filter(|v| !v.is_empty()).map(std::path::PathBuf::from)
}

/// The rig's seam (T-598), never a user's: `MESIMON_RIG_NO_FLAGS=1` launches
/// every command (panes and the road probe alike) with Claude Code's flags
/// service off, `DISABLE_GROWTHBOOK=1`, so each flag reads its built-in
/// default. It is the only local pin of `tengu_plugin_hooks_modules`, whose
/// default is on (measured on 2.1.288: the local override hooks are stubbed
/// out of the public build), and it pins every other flag to its default
/// with it. `ci/rig.py --flags-off` sets it, so the rig's acceptance can run
/// while the remote flag has mods off.
fn rig_no_flags() -> bool {
    std::env::var("MESIMON_RIG_NO_FLAGS").as_deref() == Ok("1")
}

#[cfg(test)]
mod queued_person_tests {
    use super::*;
    use crate::agents::claude::composer::Composer;

    /// T-961: a seat is young, its box perhaps not drawn, while it spawns or
    /// sits idle since its `SessionStart`, inside the composer's wait from
    /// its pane's own launch; a turn that ended, a pane past the wait, or a
    /// pane this daemon did not launch (no stamp: a recovered `StaleQuiet`
    /// seat reads `Idle{Unknown}` too, round 1) is not.
    #[test]
    fn a_seat_is_young_from_its_pane_s_launch_to_the_composer_s_wait() {
        let (wait, now) = (30_000, 1_792_888_100_000);
        let unknown = SessionState::Idle { stop_reason: StopReason::Unknown };
        assert!(young_seat(&SessionState::Spawning, Some(now - 500), now, wait));
        assert!(!young_seat(&SessionState::Spawning, None, now, wait), "no launch stamp");
        assert!(!young_seat(&unknown, None, now, wait), "a recovered pane");
        assert!(young_seat(&unknown, Some(now - 200), now, wait));
        assert!(!young_seat(&unknown, Some(now - wait), now, wait), "past the wait");
        assert!(!young_seat(&SessionState::Spawning, Some(now - wait - 1), now, wait));
        let ended = SessionState::Idle { stop_reason: StopReason::EndTurn };
        assert!(!young_seat(&ended, Some(now - 200), now, wait), "a turn ended");
        assert!(!young_seat(&SessionState::Running, Some(now - 200), now, wait));
    }

    /// T-966, round 1: a listing's clients under T-945's bound. A blank or
    /// malformed row (`None`) holds as a client that may be typing, beside an
    /// expired one too; only no row at all is nobody there.
    #[test]
    fn a_pane_s_clients_hold_unless_every_reading_is_idle_past_the_bound() {
        let (bound, at) = (5_000, 1_792_888_100_000);
        let idle = Some(at / 1000 - 60);
        let fresh = Some(at / 1000);
        assert_eq!(PaneClients::of(&[], at, bound), PaneClients::Away);
        assert_eq!(PaneClients::of(&[idle], at, bound), PaneClients::Idle);
        assert_eq!(PaneClients::of(&[idle, idle], at, bound), PaneClients::Idle);
        assert_eq!(PaneClients::of(&[fresh], at, bound), PaneClients::Here);
        assert_eq!(PaneClients::of(&[idle, fresh], at, bound), PaneClients::Here);
        assert_eq!(PaneClients::of(&[None], at, bound), PaneClients::Here, "unknown");
        assert_eq!(PaneClients::of(&[idle, None], at, bound), PaneClients::Here);
    }

    /// T-966, round 1: past clients all idle, only a box read positively
    /// empty at the edge takes the keys. A draft, a box with no composer and
    /// a capture that failed each refuse before any key, so a queue keeps
    /// its entry; with nobody there the box is not read at all.
    #[test]
    fn the_edge_types_past_an_idle_client_only_into_a_box_read_empty() {
        let refusal = |clients: PaneClients, read: Option<Composer>| {
            let mut asked = false;
            let why = clients.refusal(|| {
                asked = true;
                read
            });
            (why, asked)
        };
        assert_eq!(refusal(PaneClients::Idle, Some(Composer::Empty)), (None, true));
        assert_eq!(refusal(PaneClients::Idle, Some(Composer::Holding)), (Some(DRAFT_IN_BOX), true));
        assert_eq!(refusal(PaneClients::Idle, Some(Composer::Absent)), (Some(BOX_UNKNOWN), true));
        assert_eq!(refusal(PaneClients::Idle, None), (Some(BOX_UNKNOWN), true), "capture failed");
        assert_eq!(
            refusal(PaneClients::Here, Some(Composer::Empty)),
            (Some(PERSON_AT_PANE), false)
        );
        assert_eq!(refusal(PaneClients::Away, Some(Composer::Holding)), (None, false));
    }

    /// T-966, round 1: readiness past clients all idle releases only on a
    /// composer read empty on the sample that read the clients; any other
    /// read holds, named by the newest read so the row keeps its word.
    #[test]
    fn readiness_past_an_idle_client_releases_only_on_a_coherent_empty_box() {
        assert_eq!(idle_box(Some(Composer::Empty), true), None);
        assert_eq!(idle_box(Some(Composer::Empty), false), Some(BoxRead::Unread), "an older read");
        assert_eq!(idle_box(None, false), Some(BoxRead::Unread));
        assert_eq!(idle_box(Some(Composer::Absent), true), Some(BoxRead::Unknown));
        assert_eq!(idle_box(Some(Composer::Absent), false), Some(BoxRead::Unknown));
        assert_eq!(idle_box(Some(Composer::Holding), true), Some(BoxRead::Draft));
        assert_eq!(idle_box(Some(Composer::Holding), false), Some(BoxRead::Draft));
        assert_eq!(AskHold::Box(BoxRead::Draft).word(), Some("after your draft"));
        assert_eq!(AskHold::Box(BoxRead::Unknown).word(), Some("box unknown ∙ leave"));
        assert_eq!(AskHold::Box(BoxRead::Unread).word(), None);
    }
}

/// T-966, round 2: the row word's push, at the daemon. A pane sample that
/// changes a queued ask's word for a person broadcasts `BoardChanged` though
/// nothing else it absorbs changed; the same sample again broadcasts nothing.
#[cfg(test)]
mod queued_person_push_tests {
    use super::*;
    use std::io::{BufRead, BufReader};

    const RULE: &str = "────────────────────";

    fn screen(lines: &[&str]) -> mesimon_backend_tmux::InputScreen {
        mesimon_backend_tmux::InputScreen {
            lines: lines.iter().map(|l| l.to_string()).collect(),
            cursor: None,
        }
    }

    /// A daemon assembled as `run` assembles one, on a temporary state dir
    /// and a tmux socket nothing listens on, with one idle Claude pane and an
    /// ask queued at it.
    pub(super) fn daemon(
        dir: &std::path::Path,
    ) -> (Daemon, String, std::sync::mpsc::Receiver<Msg>) {
        let repo = dir.join("repo");
        std::fs::create_dir_all(&repo).unwrap();
        let paths = Paths {
            repo_root: repo.clone(),
            proj16: "0966096609660966".into(),
            rt_dir: dir.join("rt"),
            state_dir: dir.join("state"),
            board_dir: repo.join(".mesimon"),
        };
        paths.ensure_dirs().unwrap();
        let (tx, rx) = channel();
        let backend = TmuxBackend::new(dir.join("tmux.sock"), &paths.state_dir, None).unwrap();
        let mut board = Board::with_default_columns();
        let ticket = ulid::Ulid::new();
        let id = uuid::Uuid::new_v4();
        let cwd = repo.display().to_string();
        board.sessions.push(SessionRecord::new(
            id,
            SessionKind::Claude,
            ticket,
            vec!["claude".into()],
            cwd.clone(),
            SessionState::Idle { stop_reason: StopReason::EndTurn },
        ));
        let sid = board.sessions[0].sid16();
        let queued = vec![QueuedAsk {
            ticket,
            seat: QueuedSeat::Pane(id),
            cwd,
            text: "mesimon-probe-966 words".into(),
            queued_at: now_ms(),
            by: None,
            sends: false,
            accept_plan: false,
            send_on_accept: false,
            held: None,
            plan: false,
            deliver: Deliver::Idle,
            from_board: None,
        }];
        let feed = FeedWriter::open(&paths.activity_log()).unwrap();
        let journal = crate::journal::Journal::open(&paths.daemon_log());
        let d = Daemon::assemble(Seed {
            board,
            backend,
            journal,
            notices: Vec::new(),
            exe_stamp: None,
            own_exe: None,
            started_at: String::new(),
            worktrees_barred: false,
            queue_barred: false,
            started_barred: false,
            costs_barred: false,
            machines: HashMap::new(),
            queued,
            train_barred: false,
            forge_barred: false,
            feed,
            started: Default::default(),
            costs: Default::default(),
            worktrees: Default::default(),
            crown_barred: false,
            modroad: bridge::ModRoad::start(&paths),
            git_fetch_every: Duration::from_secs(60),
            columns_barred: false,
            sessions_barred: false,
            terminals: Default::default(),
            tx,
            self_exe: dir.join("mesimon"),
            paths,
        });
        (d, sid, rx)
    }

    /// The pane's facts: one client attached, idle past the bound by an hour.
    fn facts(sid: &str, at: u64) -> Vec<mesimon_backend_tmux::PaneFacts> {
        vec![mesimon_backend_tmux::PaneFacts {
            session_name: sid.to_string(),
            pane_pid: 0,
            pane_dead: false,
            reaped: false,
            server_pid: 1,
            current_command: "claude".into(),
            attached: true,
            activity: Some(at / 1000 - 3600),
            title: String::new(),
        }]
    }

    fn sample(
        gen: u64,
        sid: &str,
        at: u64,
        box_read: Option<mesimon_backend_tmux::InputScreen>,
    ) -> crate::panes::Sample {
        crate::panes::Sample {
            gen,
            at,
            facts: Some(facts(sid, at)),
            activity: None,
            startup: Vec::new(),
            screens: box_read.map(|b| (sid.to_string(), b)).into_iter().collect(),
            rss: None,
            rows: None,
            hook_rows: None,
            alive: None,
            access: None,
            took: Duration::ZERO,
            forks: 0,
        }
    }

    /// Every `BoardChanged` the subscriber holds now.
    fn pushes(sub: &mut BufReader<UnixStream>) -> usize {
        sub.get_ref().set_nonblocking(true).unwrap();
        let mut n = 0;
        let mut line = String::new();
        while matches!(sub.read_line(&mut line), Ok(k) if k > 0) {
            assert!(line.contains("board_changed"), "{line}");
            n += 1;
            line.clear();
        }
        n
    }

    #[test]
    fn a_sample_that_changes_a_queued_ask_s_person_word_pushes_and_the_same_one_does_not() {
        let dir = std::env::temp_dir().join(format!("msmn-t966-push-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let (mut d, sid, _rx) = daemon(&dir);
        let (ours, theirs) = UnixStream::pair().unwrap();
        d.subscribers.push(Arc::new(Mutex::new(ours)));
        let mut sub = BufReader::new(theirs);
        let words = |d: &Daemon| d.queued_person_words();
        let gen = d.pane_gen;
        let t0 = now_ms();
        // A known old box (empty, from before the client's facts) and the
        // client's facts landed alone: the box is unread on this sample.
        d.screens.insert(sid.clone(), (t0 - 60_000, screen(&[RULE, "❯ ", RULE])));
        d.on_pane_sampled(sample(gen, &sid, t0, None));
        assert_eq!(words(&d), vec![None], "held, no word: the box is unread");
        let _ = pushes(&mut sub);
        // The same facts with the box read holding words: the word moves to
        // `after your draft`, and that alone pushes.
        let draft = screen(&[RULE, "❯ half a thought", RULE]);
        d.on_pane_sampled(sample(gen, &sid, t0 + 1_000, Some(draft.clone())));
        assert_eq!(words(&d), vec![Some("after your draft")]);
        assert_eq!(pushes(&mut sub), 1, "the learned draft pushes");
        assert_eq!(d.queued.len(), 1, "the ask still waits");
        // The identical sample again: nothing moved, nothing pushes.
        d.on_pane_sampled(sample(gen, &sid, t0 + 2_000, Some(draft)));
        assert_eq!(words(&d), vec![Some("after your draft")]);
        assert_eq!(pushes(&mut sub), 0, "the same sample pushes nothing");
        // The box read as no composer: `box unknown ∙ leave`, pushed.
        let dialog = screen(&["Do you want to proceed?", "  1. Yes", "  2. No"]);
        d.on_pane_sampled(sample(gen, &sid, t0 + 3_000, Some(dialog.clone())));
        assert_eq!(words(&d), vec![Some("box unknown ∙ leave")]);
        assert_eq!(pushes(&mut sub), 1, "the unreadable box pushes");
        d.on_pane_sampled(sample(gen, &sid, t0 + 4_000, Some(dialog)));
        assert_eq!(pushes(&mut sub), 0, "and again, nothing");
        assert_eq!(d.queued.len(), 1, "the ask still waits");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// T-997: `paste_at`'s refusal for a person reads the pane afresh (here
    /// a server that answers no `list-clients`, which counts as a person),
    /// so the drain does not try the pane again on the sample that let it
    /// try, once a pass, a kept line each time; it tries again on a sample
    /// begun after the refusal.
    #[test]
    fn a_refused_queued_ask_waits_for_a_sample_from_after_its_refusal() {
        let dir = std::env::temp_dir().join(format!("msmn-t997-kept-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let (mut d, sid, _rx) = daemon(&dir);
        let feed = d.paths.activity_log();
        let kept = |d: &mut Daemon| {
            d.feed.flush().unwrap();
            std::fs::read_to_string(&feed)
                .unwrap_or_default()
                .lines()
                .filter(|l| l.contains("\"cmd\":\"queued_ask_kept\""))
                .count()
        };
        let gen = d.pane_gen;
        let empty = screen(&[RULE, "❯ ", RULE]);
        let t0 = now_ms();
        // The client idle an hour and the box read empty on one sample: the
        // drain tries, and the fresh read refuses.
        d.on_pane_sampled(sample(gen, &sid, t0, Some(empty.clone())));
        assert_eq!(kept(&mut d), 1, "the refusal keeps the ask");
        assert_eq!(d.queued.len(), 1);
        // Pass after pass on that sample, and on one begun before the
        // refusal: no second try.
        d.drain_queue();
        d.drain_queue();
        d.on_pane_sampled(sample(gen, &sid, t0, Some(empty.clone())));
        assert_eq!(kept(&mut d), 1, "the drain did not loop on an older sample");
        // A sample begun after the refusal: the drain tries again.
        d.on_pane_sampled(sample(gen, &sid, now_ms() + 1, Some(empty)));
        assert_eq!(kept(&mut d), 2, "a fresh sample lets it try");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// T-997, round 1: the refusal's stamp holds only the words a person at
    /// the pane would meet. On a mod pane that speaks `submit`, a stamped
    /// pane's plain ask goes by the submit, past the box, and is not held;
    /// a `/` command for the same pane is typed, and is.
    #[test]
    fn a_refusal_holds_a_typed_ask_and_not_one_the_mod_submits() {
        let dir = std::env::temp_dir().join(format!("msmn-t997-submit-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let (mut d, sid, _rx) = daemon(&dir);
        let id = d.board.sessions[0].id;
        d.board.sessions[0].road = Road::Mod;
        d.modroad.seat_bridge(id, &["submit"]);
        d.person_refused_at.insert(sid, now_ms());
        let submitted = d.queued[0].clone();
        assert!(d.takes_by_submit(id, &submitted.text), "the mod submits these words");
        assert!(!d.typed_under_a_person(id, &submitted), "a submit is held by no refusal");
        let typed = QueuedAsk { text: "/compact".into(), ..submitted };
        assert!(d.typed_under_a_person(id, &typed), "typed words wait for a fresh read");
        let _ = std::fs::remove_dir_all(&dir);
    }
}

#[cfg(test)]
mod crown_rules_write_tests {
    use super::*;

    /// T-930's review (b): a reply whose write fails acknowledges nothing,
    /// and one that is written acknowledges its session under its count.
    /// The write fails because this end's own sending is shut (T-971): a
    /// dropped peer is not a closed one on macOS, where `UnixStream::pair`
    /// marks the pair close-on-exec only after `socketpair`, and a test
    /// beside it that forks in that gap leaves a child holding the peer
    /// open, so the write lands (11 in 100,000 beside 200 spawns).
    #[test]
    fn only_a_written_reply_tells_the_crown() {
        let (tx, rx) = channel();
        let s = uuid::Uuid::new_v4();
        let (ours, _theirs) = UnixStream::pair().unwrap();
        ours.shutdown(std::net::Shutdown::Write).unwrap();
        assert!(!write_reply(&Mutex::new(ours), "{}", Some((s, 7)), &tx), "a failed write");
        assert!(rx.try_recv().is_err(), "nothing acknowledged");
        let (ours, _theirs) = UnixStream::pair().unwrap();
        assert!(write_reply(&Mutex::new(ours), "{}", Some((s, 7)), &tx));
        assert!(matches!(rx.try_recv(), Ok(Msg::CrownTold(got, 7)) if got == s));
    }
}

#[cfg(test)]
mod ack_cutoff_tests {
    use super::{forgotten_by_ack, Ack, Owed, Parked};

    /// The ack's cutoff is when the words went in (T-894 re-review): a
    /// parked launch's entry has none until its paste stamps it, so an ask
    /// queued after the entry's birth but before the paste was there before
    /// the words, and goes with the ack; one queued after the paste stays.
    #[test]
    fn the_cutoff_is_stamped_when_the_words_go_in() {
        let words = Parked { text: "go".into(), brief: false, title: false };
        let mut launch = Owed::launch(ulid::Ulid::nil(), words, Ack::PROMPT);
        assert_eq!(launch.sent_at, None, "parked words have not gone in");
        // An ask queued between the entry's birth and the paste.
        let between = launch.screen_after + 1_000;
        launch.sent_at = Some(between + 1_000);
        assert!(forgotten_by_ack(between, launch.sent_at), "it was there before the words");
        assert!(!forgotten_by_ack(between + 2_000, launch.sent_at), "a follow-up stays");
        let pasted = Owed::pasted(ulid::Ulid::nil(), Ack::PROMPT, 5_000);
        assert_eq!(pasted.sent_at, Some(5_000), "a live paste is stamped as it goes in");
        assert!(forgotten_by_ack(5_000, pasted.sent_at));
        assert!(!forgotten_by_ack(5_001, pasted.sent_at));
        assert!(forgotten_by_ack(u64::MAX, None), "a person's own prompt talks past any");
    }
}

