#[cfg(test)]
mod status_line_tests {
    use super::{status_left, ticket_crumb, tmux_text};

    /// The root terminal has no ticket, so the line skips the ticket crumb
    /// and its separator rather than draw an empty segment (T-489).
    #[test]
    fn the_status_line_drops_an_empty_ticket_crumb() {
        assert_eq!(
            status_left("mesimon", "", "", "terminal"),
            " mesimon › #[bold]mesimon#[nobold] › #[bold]terminal#[nobold] "
        );
        assert_eq!(
            status_left("mesimon", "", "#[bold]T-4#[nobold] fix", "claude"),
            " mesimon › #[bold]mesimon#[nobold] › #[bold]T-4#[nobold] fix › #[bold]claude#[nobold] "
        );
    }

    /// The status-line crumb names the ticket by key, then title (T-428):
    /// the key is bold, the title is capped and scrubbed the way it was.
    #[test]
    fn the_ticket_crumb_leads_with_the_key() {
        assert_eq!(ticket_crumb("T-428", "show the id"), "#[bold]T-428#[nobold] show the id");
        assert_eq!(
            ticket_crumb("T-1", ""),
            "#[bold]T-1#[nobold]",
            "no trailing space for an empty title"
        );
        let long = "x".repeat(60);
        assert_eq!(ticket_crumb("T-9", &long), format!("#[bold]T-9#[nobold] {}", "x".repeat(48)));
        // A title cannot open a tmux style: `#` doubles, quotes vanish.
        assert_eq!(ticket_crumb("T-2", "a #[fg=red] 'b'"), "#[bold]T-2#[nobold] a ##[fg=red] b");
        assert_eq!(tmux_text("T-2", 16), "T-2");
    }
}

#[cfg(test)]
mod restart_resend_tests {
    use super::restart_resends;
    use mesimon_core::board::{
        SessionKind, SessionRecord, SessionState, StopReason, UnknownReason, Unsent,
    };

    fn seat(transcript: Option<&std::path::Path>) -> SessionRecord {
        let mut rec = SessionRecord::new(
            uuid::Uuid::from_u128(7),
            SessionKind::Claude,
            ulid::Ulid::from_parts(1, 7),
            vec!["claude".into()],
            "/tmp".into(),
            SessionState::Idle { stop_reason: StopReason::Unknown },
        );
        rec.transcript_path = transcript.map(|p| p.display().to_string());
        rec.unsent = Some(Unsent { text: String::new(), brief: true });
        rec
    }

    /// T-722: a brief handed over by the last daemon goes again only to a
    /// claude at the composer `SessionStart` left whose conversation took no
    /// prompt; anything else keeps the card's mark for a person.
    #[test]
    fn a_handed_over_brief_goes_again_only_to_a_seat_that_never_took_a_prompt() {
        let dir = std::env::temp_dir().join(format!("msmn-t722-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let absent = dir.join("never.jsonl");
        let present = dir.join("took.jsonl");
        std::fs::write(&present, "{}\n").unwrap();

        assert!(restart_resends(&seat(Some(&absent)), true));
        assert!(!restart_resends(&seat(Some(&absent)), false), "found where a wake looks");
        assert!(!restart_resends(&seat(Some(&present)), true), "the conversation took one");
        assert!(!restart_resends(&seat(None), true), "no SessionStart, nothing known");

        let mut words = seat(Some(&absent));
        words.unsent = Some(Unsent { text: "go".into(), brief: false });
        assert!(!restart_resends(&words, true), "a person's words are theirs to resend");
        words.unsent = None;
        assert!(!restart_resends(&words, true), "nothing handed over");

        for state in [
            SessionState::Running,
            SessionState::Idle { stop_reason: StopReason::EndTurn },
            SessionState::Unknown { reason: UnknownReason::DaemonRestarted },
            SessionState::Sleeping,
        ] {
            let mut rec = seat(Some(&absent));
            rec.state = state.clone();
            assert!(!restart_resends(&rec, true), "{state:?}");
        }
        let mut shell = seat(Some(&absent));
        shell.kind = SessionKind::Codex;
        assert!(!restart_resends(&shell, true), "a codex keeps its own policy");
        let _ = std::fs::remove_dir_all(&dir);
    }
}

#[cfg(test)]
mod crown_refusal_tests {
    use super::crown_refused;
    use mesimon_core::mcp::lint_tool_text;

    /// T-908: a worker reaching for another ticket reads who reads it, that
    /// the crown copies what is needed onto this ticket, and that a raised
    /// hand is the road — to the crown too where the crown hears this
    /// ticket. Every keyed road (`read_note`, `get_ticket`,
    /// `read_attachment`, `read_shell`, the keyed writes) passes
    /// `crown_target`'s one `what`; `ask_board` passes its own.
    #[test]
    fn the_refusal_names_the_road() {
        for what in ["another ticket (T-9)", "a linked board"] {
            let heard = crown_refused(what, "T-5", Some("T-1"), true);
            assert_eq!(
                heard,
                format!(
                    "only the crown (T-1) reads or changes {what}; the crown can copy what is \
                     needed onto this ticket, and raise_hand on this ticket, naming what is \
                     missing, reaches the person and the crown."
                )
            );
            let unheard = crown_refused(what, "T-5", Some("T-1"), false);
            assert!(unheard.ends_with("naming what is missing, reaches the person."), "{unheard}");
            assert!(!unheard.contains("^o"), "under a crown, no second crown is offered");
            let none = crown_refused(what, "T-5", None, false);
            for words in ["no ticket wears the crown", "cursor on T-5", "^o", "raise_hand"] {
                assert!(none.contains(words), "{words}: {none}");
            }
            for text in [heard, unheard, none] {
                lint_tool_text(&text).unwrap();
            }
        }
    }
}

