#[cfg(test)]
mod permission_release_tests {
    use super::releases_permission;
    use crate::ingest::HookFrame;
    use mesimon_core::road::Road;
    use serde_json::json;

    fn frame(event: &str, road: Road, payload: serde_json::Value) -> HookFrame {
        HookFrame {
            session: uuid::Uuid::nil().to_string(),
            event: event.into(),
            reason: None,
            pane: None,
            road,
            payload,
        }
    }

    /// T-581: the mod's hold in `classic.PermissionRequest` runs on until
    /// the daemon closes `mesimon approve`'s wait, and the person answering
    /// the dialog in the pane is the `PostToolUse` edge the mod relays, read
    /// exactly as the hook set's.
    #[test]
    fn the_session_s_own_edge_ends_the_wait_on_either_road() {
        for road in [Road::Hooks, Road::Mod] {
            for event in
                ["PostToolUse", "PostToolUseFailure", "Stop", "UserPromptSubmit", "SessionEnd"]
            {
                assert!(releases_permission(&frame(event, road, json!({}))), "{event} {road:?}");
            }
            // A subagent's tool, or a frame that says nothing of the dialog.
            assert!(!releases_permission(&frame("PostToolUse", road, json!({"agent_id": "a7"}))));
            for event in ["PreToolUse", "PermissionRequest", "Notification", "ModUsage"] {
                assert!(!releases_permission(&frame(event, road, json!({}))), "{event}");
            }
        }
    }
}

#[cfg(test)]
mod shell_archive_regressions {
    use super::*;

    #[test]
    fn archive_offer_excludes_awake_shells_without_foreground_decoration() {
        let ticket = ulid::Ulid(1);
        let mut board = Board::default();
        assert!(archive_offer_old_enough(&board, ticket, "@1", 10_000, 5_000));
        let mut shell = SessionRecord::new(
            uuid::Uuid::nil(),
            SessionKind::Bash,
            ticket,
            vec!["sh".into()],
            "/repo".into(),
            SessionState::Running,
        );
        shell.state_changed_at = Some(1_000);
        assert!(shell.foreground.is_none()); // Exactly what the writer keeps, busy or idle.
        board.sessions.push(shell);
        assert!(!archive_offer_old_enough(&board, ticket, "@1", 10_000, 5_000));
        // A second shell cannot make a partial archive: either awake shell excludes the ticket.
        let mut second = board.sessions[0].clone();
        second.id = uuid::Uuid::from_u128(2);
        board.sessions.push(second);
        board.sessions[0].state = SessionState::Sleeping;
        assert!(!archive_offer_old_enough(&board, ticket, "@1", 10_000, 5_000));
        board.sessions[1].state = SessionState::Sleeping;
        assert!(archive_offer_old_enough(&board, ticket, "@1", 10_000, 5_000));
        board.sessions[1].state_changed_at = Some(9_000);
        assert!(!archive_offer_old_enough(&board, ticket, "@1", 10_000, 5_000));
    }

    #[test]
    fn a_shell_child_check_must_prove_idle_before_close() {
        for (status, text) in [
            (Some(0), &b"42 \xff"[..]),
            (Some(2), &b""[..]),
            (None, &b""[..]),
            (Some(0), &b"42"[..]),
        ] {
            let evidence = shells::parse_children(status, text);
            let error = evidence.clone().unwrap_err();
            assert_eq!(shell_children_idle(evidence), Err(error));
        }
        assert!(shell_children_idle(shells::parse_children(Some(0), b"42 sleep\n"))
            .unwrap_err()
            .contains("live children"));
        assert!(shell_children_idle(shells::parse_children(Some(1), b"")).is_ok());
    }
}
